MUTATIONS:
match self {
    Self::NotAllowed { service, method } => {
        write!(
            f,
            "service {service} method {method} is not on the allow-list"
        )
    }
    Self::Engine { error } => {
        write!(f, "the engine refused the call ({} bytes)", error.len())
    }
    Self::Start { reason } => write!(f, "the engine could not start: {reason}"),
}

#[cfg(feature = "bindgen")]
uniffi::uniffi_bindgen_swift();
#[cfg(not(feature = "bindgen"))]
{
    eprintln!(
        "uniffi-bindgen-swift: this build holds no Swift bindings generator, because it was \
         built without the `bindgen` feature; run it as `cargo run -p deck-streak-ffi \
         --features bindgen --bin uniffi-bindgen-swift -- <arguments>`"
    );
    std::process::exit(2);
}
